import sys, re

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pos = 1
    parent, tag, ident, classes = [], [], [], []
    for _ in range(n):
        parent.append(int(data[pos]))
        tag.append(data[pos + 1])
        ident.append(data[pos + 2])
        c = int(data[pos + 3])
        classes.append(frozenset(data[pos + 4:pos + 4 + c]))
        pos += 4 + c
    q = int(data[pos])
    pos += 1
    part = re.compile(r'([#.])([a-z0-9]+)')
    def parse(s):
        j = 0
        while j < len(s) and s[j] not in '#.':
            j += 1
        t = s[:j]
        if t == '*' or t == '':
            t = None
        ids, cls = [], []
        for kind, name in part.findall(s[j:]):
            (ids if kind == '#' else cls).append(name)
        return (t, ids, cls)
    def match(v, comp):
        t, ids, cls = comp
        if t is not None and tag[v] != t:
            return False
        for i in ids:
            if ident[v] != i:
                return False
        cv = classes[v]
        for c in cls:
            if c not in cv:
                return False
        return True
    out = []
    for _ in range(q):
        t = int(data[pos])
        comps = [parse(s) for s in data[pos + 1:pos + 1 + t]]
        pos += 1 + t
        last = comps[t - 1]
        st = [0] * n
        count, first = 0, -1
        for v in range(n):
            p = parent[v]
            s = st[p] if p >= 0 else 0
            ml = match(v, last)
            if ml and s >= t - 1:
                count += 1
                if first < 0:
                    first = v
            if s < t:
                st[v] = s + 1 if (ml if s == t - 1 else match(v, comps[s])) else s
            else:
                st[v] = s
        out.append('%d %d' % (count, first))
    print('\n'.join(out))

