import sys, re

data = sys.stdin.read().split()
n = int(data[0])
pos = 1
parent, tag, ident, classes = [], [], [], []
for _ in range(n):
    parent.append(int(data[pos]))
    tag.append(data[pos + 1])
    ident.append(data[pos + 2])
    c = int(data[pos + 3])
    classes.append(set(data[pos + 4:pos + 4 + c]))
    pos += 4 + c
q = int(data[pos])
pos += 1

def parse(s):
    m = re.match(r'^(\*|[a-z0-9]*)((?:[#.][a-z0-9]+)*)$', s)
    t = m.group(1) or None
    if t == '*':
        t = None
    parts = re.findall(r'([#.])([a-z0-9]+)', m.group(2))
    return t, parts

def ok(v, comp):
    t, parts = comp
    if t is not None and tag[v] != t:
        return False
    for kind, name in parts:
        if kind == '#' and ident[v] != name:
            return False
        if kind == '.' and name not in classes[v]:
            return False
    return True

def ancestors(v):
    res = []
    p = parent[v]
    while p >= 0:
        res.append(p)
        p = parent[p]
    return res

def matches(v, comps, i):
    if not ok(v, comps[i]):
        return False
    if i == 0:
        return True
    return any(matches(a, comps, i - 1) for a in ancestors(v))

for _ in range(q):
    t = int(data[pos])
    comps = [parse(s) for s in data[pos + 1:pos + 1 + t]]
    pos += 1 + t
    res = [v for v in range(n) if matches(v, comps, t - 1)]
    print(len(res), res[0] if res else -1)

