import java.util.*;
import java.io.*;

public class Main {
    static int[] query(int[] parent, String[] tag, String[] ident, String[][] classes, String[] selector) {
        // Write your solution here
        // selector is the list of compound selectors, e.g. {"div.box", "span"}
        // Return {number of matching elements, index of the first match or -1}
        return new int[] { 0, -1 };
    }

    public static void main(String[] args) throws IOException {
        String[] tk = new String(System.in.readAllBytes()).trim().split("\\s+");
        int p = 0;
        int n = Integer.parseInt(tk[p++]);
        int[] parent = new int[n];
        String[] tag = new String[n], ident = new String[n];
        String[][] classes = new String[n][];
        for (int i = 0; i < n; i++) {
            parent[i] = Integer.parseInt(tk[p++]);
            tag[i] = tk[p++];
            ident[i] = tk[p++];
            int c = Integer.parseInt(tk[p++]);
            classes[i] = new String[c];
            for (int j = 0; j < c; j++) classes[i][j] = tk[p++];
        }
        int q = Integer.parseInt(tk[p++]);
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            int t = Integer.parseInt(tk[p++]);
            String[] selector = new String[t];
            for (int i = 0; i < t; i++) selector[i] = tk[p++];
            int[] r = query(parent, tag, ident, classes, selector);
            sb.append(r[0]).append(' ').append(r[1]).append('\n');
        }
        System.out.print(sb);
    }
}
